from jsonb_to_recordset($wall_questions$[{"id":"u04_l03_q157","lesson_id":"u04_l03","difficulty":"medium","prompt":"ما الصلة بين الصدق والوفاء بالعهد ومنهج الوقاية من الجريمة؟","options":[{"id":"o4","text":"أن الأخلاق تقتصر على العبادات الخاصة"},{"id":"o3","text":"أن الوفاء بالعهد وسيلة لإخفاء الجريمة"},{"id":"o2","text":"أن الفضائل لا تؤثر في المعاملة بين الناس"},{"id":"o1","text":"أن تعزيز الأخلاق يقلل دوافع الاعتداء والخداع"}],"correct_id":"o1","explanation":"جعل الكتاب تعميق الجانب الأخلاقي من وسائل الوقاية.","page":156},{"id":"u04_l03_q166","lesson_id":"u04_l03","difficulty":"hard","prompt":"ما المقصود بمزاوجة التدابير الوقائية والعلاجية في منهج مكافحة الجريمة؟","options":[{"id":"o2","text":"الاكتفاء بالعقاب دون معالجة أسباب المشكلة"},{"id":"o4","text":"ترك كل مخالفة دون محاسبة"},{"id":"o1","text":"منع أسباب الجريمة قدر الإمكان والتعامل مع المخالفة وفق الشرع والقانون عند وقوعها"},{"id":"o3","text":"إلغاء الإصلاح والاقتصار على المواعظ"}],"correct_id":"o1","explanation":"قسم الكتاب المنهج إلى وقاية تحد من الأسباب وعلاج يعالج ما وقع.","page":155},{"id":"u04_l03_q178","lesson_id":"u04_l03","difficulty":"medium","prompt":"لماذا حصر الإسلام تنفيذ العقوبات في الحاكم أو من ينوب عنه؟","options":[{"id":"o2","text":"لإتاحة العقوبة لكل فرد بحسب غضبه"},{"id":"o3","text":"لإسقاط مسؤولية المؤسسات الرسمية"},{"id":"o1","text":"لمنع الفوضى والتجاوز في أخذ الحقوق"},{"id":"o4","text":"لإلغاء الحاجة إلى الفصل بين الخصومات"}],"correct_id":"o1","explanation":"نص الدرس على أن اختصاص السلطة بتنفيذ العقوبات يحفظ النظام ويمنع الاعتداء.","page":157},{"id":"u04_l03_q182","lesson_id":"u04_l03","difficulty":"hard","prompt":"لماذا تمتد آثار الجريمة من الفرد إلى المجتمع حتى حين يقع الضرر أولًا على شخص واحد؟","options":[{"id":"o4","text":"لأن حماية الحقوق مسألة فردية محضة"},{"id":"o3","text":"لأن المجتمع لا يتحمل آثار الاضطراب"},{"id":"o1","text":"لأن العدوان يضعف الثقة والأمن والروابط بين الناس"},{"id":"o2","text":"لأن الجريمة لا تؤثر في مشاعر الآخرين إطلاقًا"}],"correct_id":"o1","explanation":"عرض الدرس آثار الجريمة على أمن المجتمع وعلاقاته واقتصاده.","page":153},{"id":"u04_l03_q186","lesson_id":"u04_l03","difficulty":"hard","prompt":"ما الذي يميز القصاص عن العقوبة في حالة الاعتداء الخطأ وفق العرض التعليمي؟","options":[{"id":"o1","text":"يراعي قصد الاعتداء ويذكر الدية في الخطأ بدل معاملة الحالين معاملة واحدة"},{"id":"o2","text":"يجعل كل خطأ عمدًا بالضرورة"},{"id":"o3","text":"يسقط حقوق المتضررين في الحالتين"},{"id":"o4","text":"يترك للناس العقوبة خارج القضاء"}],"correct_id":"o1","explanation":"فرّق الدرس بين الاعتداء العمد والخطأ وحقوق أصحاب الشأن في القصاص والدية.","page":155},{"id":"u04_l03_q188","lesson_id":"u04_l03","difficulty":"hard","prompt":"ما الدور الذي تؤديه التربية الأخلاقية قبل وقوع المخالفة في منهج مكافحة الجريمة؟","options":[{"id":"o3","text":"تستبدل كل وسيلة إصلاح بتشهير عام"},{"id":"o4","text":"تمنع المجتمع من العمل على الوقاية"},{"id":"o2","text":"تعد إجراء جزائيًا بعد إدانة كل الناس"},{"id":"o1","text":"تعد تدبيرًا وقائيًا يعالج الدوافع قبل حدوث الجريمة"}],"correct_id":"o1","explanation":"قسم الدرس أساليب المكافحة إلى تدابير وقائية وأخرى علاجية.","page":157},{"id":"u04_l04_q096","lesson_id":"u04_l04","difficulty":"medium","prompt":"عندما يطرح المتحدث سؤالًا ثم يشرك الحضور في الجواب، أي أسلوب من أساليب خطبة الوداع يستخدم؟","options":[{"id":"o1","text":"التشويق بإشراك المستمعين في الحوار"},{"id":"o2","text":"الإطالة بغير حاجة"},{"id":"o3","text":"إهمال انتباه الجمهور"},{"id":"o4","text":"تجنب الأمثلة والتشبيه"}],"correct_id":"o1","explanation":"ذكر الدرس أسلوب السؤال والحوار لجذب الانتباه.","page":164},{"id":"u04_l04_q105","lesson_id":"u04_l04","difficulty":"medium","prompt":"لماذا شبّه النبي ﷺ حرمة أموال الناس ودمائهم بحرمة اليوم والشهر والبلد؟","options":[{"id":"o3","text":"للدلالة على جواز انتهاكها بعد الحج"},{"id":"o4","text":"لإهمال حقوق الآخرين عند السفر"},{"id":"o2","text":"لبيان أن حرمتها مؤقتة في الحج فقط"},{"id":"o1","text":"لتأكيد عظم حرمتها لدى السامعين"}],"correct_id":"o1","explanation":"شرح الدرس أن التشبيه باليوم والشهر و