الثأر وأكد معالجة الجنايات ضمن أحكام القضاء.","page":162},{"id":"u04_l04_q116","lesson_id":"u04_l04","difficulty":"medium","prompt":"كيف ينسجم الإحسان إلى المرأة وأداء حقوقها مع وصية النبي ﷺ في حجة الوداع؟","options":[{"id":"o1","text":"يحقق تكريمها وحسن معاشرتها بالمعروف"},{"id":"o2","text":"يجيز منعها من حقوقها المقررة"},{"id":"o4","text":"يجعل الإساءة وسيلة لتربية المجتمع"},{"id":"o3","text":"ينفي التزام الأسرة بالمعاملة الحسنة"}],"correct_id":"o1","explanation":"شرح الكتاب وصية التقوى في النساء بحفظ الكرامة والإحسان وأداء الحقوق.","page":163},{"id":"u04_l04_q117","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما الغرض البلاغي لتوجيه أسئلة للجمهور عن اليوم والبلد والشهر في خطبة حجة الوداع؟","options":[{"id":"o4","text":"استبدال بيان الحقوق بموضوعات تاريخية"},{"id":"o1","text":"إشراك السامعين وإثارة انتباههم قبل تقرير الحكم"},{"id":"o3","text":"إطالة الخطبة دون هدف"},{"id":"o2","text":"اختبار معلوماتهم الجغرافية دون رسالة أخرى"}],"correct_id":"o1","explanation":"أورد الدرس السؤال ضمن أساليب التشويق ومشاركة الجمهور في الحوار.","page":164},{"id":"u04_l04_q123","lesson_id":"u04_l04","difficulty":"hard","prompt":"ما المغزى من تكرار النبي ﷺ أسئلة الحضور عن اليوم والشهر والبلد قبل بيان حرمة الحقوق؟","options":[{"id":"o3","text":"الإذن بالاعتداء خارج المكان المذكور"},{"id":"o2","text":"اختبار معلوماتهم الجغرافية بوصفه هدف الخطبة"},{"id":"o4","text":"حصر الحرمة في يوم الحج وحده"},{"id":"o1","text":"ترسيخ المعنى في النفوس بمقارنة حرمتها بحرمة الزمان والمكان"}],"correct_id":"o1","explanation":"استخدم النبي ﷺ السؤال والمقارنة لتأكيد عظمة حرمة الحقوق في نفوس السامعين.","page":161},{"id":"u04_l04_q124","lesson_id":"u04_l04","difficulty":"medium","prompt":"لماذا يُعد تحريم أكل أموال الآخرين بالباطل جزءًا من رسالة الوصايا؟","options":[{"id":"o4","text":"لأنه يجعل المال العام بلا حرمة"},{"id":"o3","text":"لأنه يبيح الغش في المعاملات"},{"id":"o2","text":"لأنه يلغي مشروعية العمل والكسب"},{"id":"o1","text":"لأنه يؤكد عدل التعامل ومنع التعدي على حقوق الناس"}],"correct_id":"o1","explanation":"تؤكد الوصايا صيانة الأموال ومنع الظلم في المعاملات.","page":161},{"id":"u04_l04_q126","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما أثر التزام المسلمين بالتوجيه النبوي بعدم العودة إلى الاقتتال الداخلي؟","options":[{"id":"o2","text":"توسيع الخصومات بين الجماعات"},{"id":"o1","text":"حماية وحدة المجتمع وحق أفراده في الأمن"},{"id":"o3","text":"إهدار حرمة الدماء في النزاعات"},{"id":"o4","text":"إلغاء التعاون بين أفراد المجتمع"}],"correct_id":"o1","explanation":"ورد التحذير من الاقتتال الداخلي ضمن الوصايا التي تحفظ أمن الناس ووحدتهم.","page":162},{"id":"u04_l04_q128","lesson_id":"u04_l04","difficulty":"medium","prompt":"أي سلوك في الأسرة يعبّر عن فهم الوصية النبوية المتعلقة بالنساء؟","options":[{"id":"o4","text":"اعتبار الظلم وسيلة مقبولة لحل المشكلات"},{"id":"o1","text":"التعامل بالمعروف وأداء الحقوق دون إضرار"},{"id":"o3","text":"إفشاء الأسرار للإساءة المتعمدة"},{"id":"o2","text":"إهمال الحقوق عند حدوث خلاف"}],"correct_id":"o1","explanation":"تناولت الوصايا صيانة حقوق النساء وحسن معاملتهن.","page":163},{"id":"u04_l04_q129","lesson_id":"u04_l04","difficulty":"medium","prompt":"أي أسلوب خطاب يساعد على فهم كيفية تعليم النبي ﷺ الناس في حجة الوداع؟","options":[{"id":"o1","text":"توجيه الأسئلة وتنبيه السامعين إلى المعاني المهمة"},{"id":"o3","text":"الابتعاد عن أي أمثلة أو مقارنة"},{"id":"o4","text":"الاكتفاء بذكر التواريخ دون قيم"},{"id":"o2","text":"الاقتصار على تعليمات غامضة بلا شرح"}],"correct_id":"o1","explanation":"عرض الدرس وسائل توجيه السامعين وتأكيد المعاني بأساليب واضحة مؤثرة.","page":164},{"id":"u04_l04_q133","lesson_id":"u04_l04","difficulty":"medium","prompt":"افتتح النبي ﷺ خطابه في حجة الوداع بعبارة «أيها الناس»؛ فما الأسلوب الخطابي المقصود؟","options":[{"id":"o4","text":"الحوار السري مع فرد واحد"},{"id":"o2","text":"المقارنة العددية بين الشهور"},{"id":"o1","text":"النداء لجذب انتباه السامعين"},{"id":"o3","text":"سرد الأسماء دون مخاطبة"}],"correct_id":"o1","explanation":"عدّ الدرس أسلوب النداء في افتتاح الخطبة وسيلة لإثارة انتباه الجمهور.","page":164},{"id":"u04_l04_q135","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما المبدأ الذي قرره النبي ﷺ بإبطال معاملات الربا التي اعتادها الناس في الجاهلية؟","options":[{"id":"o2","text":"إباحة مضاعفة الديون على الضعفاء"},{"id":"o3","text":"تقنين زيادة الدين بلا ضوابط"},{"id":"o4","text":"إلغاء حق استرداد أصل المال المشروع"},{"id":"o1","text":"منع استغلال حاجة الناس في المعاملات المالية"}],"correct_id":"o1","explanation":"أوضح الدرس أن الربا في الجاهلية استغلال لحاجة المقترض وأن الخطبة أبطلته.","page":162},{"id":"u04_l04_q139","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما التطبيق الأقرب لوصية النبي ﷺ المتعلقة بالمرأة في حجة الوداع؟","options":[{"id":"o1","text":"الإحسان إلى النساء وأداء حقوقهن وحسن معاملتهن"},{"id":"o3","text":"الاعتداء على كرامتها"},{"id":"o4","text":"إهمال واجبات الأسرة نحوها"},{"id":"o2","text":"منع المرأة من حقوقها المشروعة"}],"correct_id":"o1","explanation":"جاء في شرح الوصية التأكيد على كرامة المرأة والإحسان إليها وأداء حقوقها.","page":163},{"id":"u04_l04_q140","lesson_id":"u04_l04","difficulty":"hard","prompt":"ما الأسلوب الخطابي المستخدم في سؤال النبي ﷺ الناس عن اليوم والبلد والشهر قبل تقرير وصيته؟","options":[{"id":"o3","text":"كتابة رسالة خاصة لكل شخص"},{"id":"o1","text":"الحوار والتشويق بإشراك السامعين في الإجابة"},{"id":"o2","text":"عرض أرقام اقتصادية مجردة"},{"id":"o4","text":"الاقتصار على خطاب بلا أسئلة"}],"correct_id":"o1","explanation":"عدد الدرس إشراك الناس في الحوار وتوجيه الأسئلة من وسائل تشويق السامعين.","page":164},{"id":"u04_l04_q142","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما الدلالة التربوية لعبارة «افعل ولا حرج» في موقف السؤال عن ترتيب بعض أعمال الحج؟","options":[{"id":"o2","text":"إلغاء أحكام الحج كلها"},{"id":"o4","text":"اشتراط تكرار الحج كل سنة"},{"id":"o1","text":"التيسير على السائل في الحالات التي أقرها النبي ﷺ"},{"id":"o3","text":"منع الناس من الاستفسار عن العبادة"}],"correct_id":"o1","explanation":"ذكر التمهيد استجابة النبي ﷺ لأسئلة بعض ترتيب أعمال يوم النحر بالتيسير.","page":159},{"id":"u04_l04_q144","lesson_id":"u04_l04","difficulty":"medium","prompt":"كيف يُترجم مبدأ المساواة في وصايا حجة الوداع عند التعامل مع شخص ذي مكانة اجتماعية عالية؟","options":[{"id":"o2","text":"إعفاؤه من كل مسؤولية اجتماعية"},{"id":"o3","text":"اعتبار ثروته معيار التفاضل أمام القانون"},{"id":"o4","text":"منحه حق الاعتداء على غيره"},{"id":"o1","text":"تطبيق الحقوق والواجبات عليه دون محاباة بسبب مكانته"}],"correct_id":"o1","explanation":"ذكر الدرس المساواة في الحقوق والواجبات والجزاء دون اعتبار للعرق أو المال أو الجاه.","page":161},{"id":"u04_l04_q145","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما وجه القدوة في بدء النبي ﷺ بإبطال الربا الذي ارتبط بأقربائه؟","options":[{"id":"o2","text":"جعل المعاملة الربوية مباحة للأقارب"},{"id":"o1","text":"إظهار أن التحريم يُطبق على القريب قبل غيره دون استثناء"},{"id":"o3","text":"تأخير الإصلاح إلى ما بعد وفاة الأقارب"},{"id":"o4","text":"اعتبار النسب مبررًا للربا"}],"correct_id":"o1","explanation":"ذكر الكتاب إبطال ربا العباس مثالًا للقدوة العملية في ترك عادات الجاهلية.","page":162},{"id":"u04_l04_q147","lesson_id":"u04_l04","difficulty":"medium","prompt":"لماذا لا يُعدّ التمسك بكتاب الله في وصايا الوداع انفصالًا عن السنة النبوية وفق الشرح؟","options":[{"id":"o4","text":"لأن السنة كانت مجرد أحداث تاريخية بلا هداية"},{"id":"o1","text":"لأن القرآن يأمر بالأخذ بهدي النبي ﷺ وسنته"},{"id":"o3","text":"لأن التمسك بالقرآن يعني ترك جميع التفاسير"},{"id":"o2","text":"لأن السنة لا تتناول أي حكم"}],"correct_id":"o1","explanation":"بيّن الكتاب أن الاعتصام بالقرآن يشمل السنة لأن القرآن يأمر باتباع النبي ﷺ.","page":163},{"id":"u04_l04_q151","lesson_id":"u04_l04","difficulty":"medium","prompt":"لماذا خاطب النبي ﷺ جمع الناس في حجة الوداع بتوجيهات عامة شاملة؟","options":[{"id":"o4","text":"لحصر الدين في قضية مالية واحدة"},{"id":"o1","text":"لتثبيت الحقوق والقيم التي يحتاجها المجتمع بعد تبليغ الرسالة"},{"id":"o2","text":"لتخصيص الوصايا بفئة واحدة من الناس"},{"id":"o3","text":"لإلغاء مسؤولية الناس عن أفعالهم"}],"correct_id":"o1","explanation":"عرض الدرس الوصايا العامة في حجة الوداع بوصفها توجيهات لحماية الحقوق.","page":160},{"id":"u04_l04_q152","lesson_id":"u04_l04","difficulty":"hard","prompt":"بماذا يُستدل من مساواة حرمة الدماء والأموال والأعراض بحرمة الزمان والمكان في الخطبة؟","options":[{"id":"o1","text":"التأكيد البالغ على صيانة حقوق الإنسان"},{"id":"o2","text":"أن حرمة المكان تُلغي حقوق الناس"},{"id":"o3","text":"أن المال وحده هو المحترم دون الإنسان"},{"id":"o4","text":"أن النصيحة لا صلة لها بالأمن العام"}],"correct_id":"o1","explanation":"أبرز الدرس تشبيه حرمة الحقوق بحرمة اليوم والبلد والشهر.","page":161},{"id":"u04_l04_q154","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما المقصود بإبطال ربا العباس رضي الله عنه في وصايا حجة الوداع؟","options":[{"id":"o3","text":"أن الربا يبقى مشروعًا إذا اتصل بالأسرة"},{"id":"o2","text":"أنه استثنى أقرباءه من النهي عن الربا"},{"id":"o1","text":"أن النبي ﷺ بدأ بأقربائه ليكون تطبيق الحكم قدوة للجميع"},{"id":"o4","text":"أن المال لا يخضع لأي حكم شرعي"}],"correct_id":"o1","explanation":"أكد الدرس بدء النبي ﷺ بإبطال ربا عمه ليضرب المثال في الالتزام.","page":162},{"id":"u04_l04_q157","lesson_id":"u04_l04","difficulty":"medium","prompt":"أي أسلوب خطابي يستعمل حين يوجّه المتحدث سؤالًا إلى سامعيه ويتيح مشاركتهم في الجواب؟","options":[{"id":"o4","text":"الابتعاد عن كل مثال وتشبيه"},{"id":"o3","text":"تقديم خطاب لا يفهمه المخاطب"},{"id":"o2","text":"إلغاء دور المستمع نهائيًا"},{"id":"o1","text":"الحوار والتشويق بإشراك الجمهور"}],"correct_id":"o1","explanation":"عدّ الكتاب السؤال والحوار من أساليب تأثير خطبة حجة الوداع.","page":164},{"id":"u04_l04_q164","lesson_id":"u04_l04","difficulty":"hard","prompt":"ما الفرق بين معالجة الربا الموروث من الجاهلية والالتزام بحقوق الناس في وصايا النبي ﷺ؟","options":[{"id":"o4","text":"إباحة الاستيلاء على أموال الضعفاء"},{"id":"o1","text":"إبطال الربا الجاهلي مع تثبيت العدل وعدم التعدي على الأموال"},{"id":"o3","text":"جعل حق الدائن مفتوحًا دون قيود"},{"id":"o2","text":"إجازة كل زيادة ربوية لمن كان صاحب سلطة"}],"correct_id":"o1","explanation":"ذكر الدرس إبطال الربا الجاهلي بوصفه حماية للحقوق المالية.","page":161},{"id":"u04_l04_q176","lesson_id":"u04_l04","difficulty":"medium","prompt":"لماذا بدأ النبي ﷺ بإبطال معاملة ربوية تخص قريبًا له؟","options":[{"id":"o2","text":"ليسمح لأقاربه باستثناءات مالية"},{"id":"o3","text":"ليقرر أن الأحكام تخص غير الأقارب"},{"id":"o4","text":"ليثبت أن المعاملات المالية بلا مسؤولية"},{"id":"o1","text":"ليكون قدوة في تطبيق الأحكام قبل مطالبة الآخرين بها"}],"correct_id":"o1","explanation":"استدل الكتاب بإبطال ربا العباس على القدوة في الالتزام بالأحكام العامة.","page":162},{"id":"u04_l04_q178","lesson_id":"u04_l04","difficulty":"medium","prompt":"عندما استعمل النبي ﷺ أسلوب التشبيه بقدسية الزمان والمكان، ماذا أراد تحقيقه؟","options":[{"id":"o1","text":"تقريب معنى حرمة الحقوق إلى أذهان السامعين"},{"id":"o4","text":"حصر الحقوق في مكان وزمان واحد"},{"id":"o2","text":"صرف السامعين عن موضوع الخطبة"},{"id":"o3","text":"إلغاء الحاجة إلى فهم مضمون الخطاب"}],"correct_id":"o1","explanation":"صنّف الكتاب التشبيه ضمن وسائل الإبلاغ المؤثرة في خطبة حجة الوداع.","page":164},{"id":"u04_l04_q182","lesson_id":"u04_l04","difficulty":"hard","prompt":"رأى شخص أن مكانة الإنسان تستمد من نسبه أو لونه، فأي معيار للمفاضلة يرد عليه من وصايا حجة الوداع؟","options":[{"id":"o2","text":"الثراء ومكانة الأسرة وحدهما"},{"id":"o4","text":"السلطة السياسية مع إهمال الأخلاق"},{"id":"o3","text":"الانتماء القبلي بغض النظر عن العمل"},{"id":"o1","text":"التقوى والعمل الصالح لا الأصل واللون"}],"correct_id":"o1","explanation":"أكد النبي ﷺ في وصايا حجة الوداع أن التفاضل عند الله بالتقوى والعمل الصالح لا بالنسب أو اللون.","page":161},{"id":"u04_l04_q183","lesson_id":"u04_l04","difficulty":"medium","prompt":"ما القيمة التي يؤكدها إبطال بعض عادات الجاهلية في وصايا حجة الوداع؟","options":[{"id":"o1","text":"إقامة العلاقات على الحق والعدل بدل الظلم والثأر"},{"id":"o3","text":"تقديم العصبية على حقوق الآخرين"},{"id":"o4","text":"إعفاء الأقوياء من الواجبات"},{"id":"o2","text":"إحياء المظالم القديمة بوصفها حقًا دائمًا"}],"correct_id":"o1","explanation":"تناول الكتاب إبطال النبي ﷺ للعادات الجاهلية الضارة وترسيخ العدل.","page":161},{"id":"u04_l04_q187","lesson_id":"u04_l04","difficulty":"medium","prompt":"لماذا كان النداء المتكرر للناس في خطبة حجة الوداع أسلوبًا مؤثرًا؟","options":[{"id":"o2","text":"لمنع الناس من متابعة الحديث"},{"id":"o3","text":"لأن الخطبة اقتصرت على سؤال لغوي"},{"id":"o1","text":"لاستدعاء الانتباه قبل إبلاغ الوصايا المهمة"},{"id":"o4","text":"لأنه يغني عن بيان مضمون الوصية"}],"correct_id":"o1","explanation":"ذكر الكتاب أسلوب النداء لجذب انتباه المخاطبين.","page":164},{"id":"u04_l04_q188","lesson_id":"u04_l04","difficulty":"hard","prompt":"خطيب يشرح حقًا عظيمًا بعبارات قليلة جامعة بدل إطالة تشتت المستمعين؛ أي أسلوب نبوي يطبقه من شرح خطبة الوداع؟","options":[{"id":"o1","text":"الإيجاز والاختصار بعبارات بليغة مؤثرة"},{"id":"o2","text":"الإكثار من التكرار الذي يحجب المعنى"},{"id":"o3","text":"إلغاء الأمثلة والوصايا من الخطبة"},{"id":"o4","text":"حصر الخطاب في أسماء الأماكن دون هدف"}],"correct_id":"o1","explanation":"عدّ الكتاب الإيجاز والاختصار من الأساليب المؤثرة في وصايا حجة الوداع.","page":164},{"id":"u04_l05_q108","lesson_id":"u04_l05","difficulty":"medium","prompt":"بأي وجه عُدّ وصف السيدة خديجة رضي الله عنها للنبي ﷺ نموذجًا للمسؤولية المجتمعية؟","options":[{"id":"o1","text":"إبرازه صلة الرحم ومساعدة الضعيف وإكرام الضيف"},{"id":"o2","text":"تشجيعه على ترك صلاته بالناس"},{"id":"o4","text":"حصر الخير في منافع الأقارب المادية"},{"id":"o3","text":"الدعوة إلى الانعزال عن المجتمع"}],"correct_id":"o1","explanation":"أورد الكتاب وصف خديجة رضي الله عنها لإحسانه ﷺ للناس.","page":169},{"id":"u04_l05_q115","lesson_id":"u04_l05","difficulty":"medium","prompt":"مجموعة تدقّق إشاعة قبل نشرها لحماية استقرار مجتمعها؛ أي صورة للمسؤولية تمارس؟","options":[{"id":"o4","text":"حصر المسؤولية في التبرع المالي"},{"id":"o3","text":"التخلي عن المصالح العامة"},{"id":"o2","text":"تقوية الشائعات لتحقيق الشهرة"},{"id":"o1","text":"المحافظة على أمن المجتمع والتصدي للشائعات"}],"correct_id":"o1","explanation":"نص الكتاب على التصدي للشائعات والأكاذيب ضمن حماية أمن المجتمع.","page":168},{"id":"u04_l05_q117","lesson_id":"u04_l05","difficulty":"medium","prompt":"أي صورة من المسؤولية المجتمعية تعالج النزاع مباشرة قبل تحوله إلى خصومة واسعة؟","options":[{"id":"o2","text":"توسيع الشائعات عن الأطراف"},{"id":"o1","text":"الإصلاح بين المتخاصمين وتعزيز التسامح"},{"id":"o3","text":"منع أي محاولة للحوار"},{"id":"o4","text":"التشجيع على القطيعة الدائمة"}],"correct_id":"o1","explanation":"ذكر الدرس الإصلاح بين الناس وحل الخلافات وتقوية المودة ضمن صور المسؤولية.","page":168},{"id":"u04_l05_q123","lesson_id":"u04_l05","difficulty":"hard","prompt":"لماذا يُعد توفير الطعام والمأوى والرعاية الصحية للمحتاجين ممارسة متكاملة للمسؤولية المجتمعية؟","options":[{"id":"o2","text":"لأنه يقتصر على تقديم نصائح لفظية"},{"id":"o1","text":"لأنه يستجيب لأكثر من حاجة أساسية ويخفف معاناة أفراد المجتمع"},{"id":"o3","text":"لأنه يمنع المحتاجين من الحصول على العون"},{"id":"o4","text":"لأنه يجعل الدعم حكرًا على أصحاب الوظائف"}],"correct_id":"o1","explanation":"وضع الدرس توفير الغذاء والمأوى والرعاية الصحية ضمن مجالات مساعدة الضعفاء.","page":168},{"id":"u04_l05_q125","lesson_id":"u04_l05","difficulty":"hard","prompt":"ما الذي يجعل دعم مشروع يساعد ذوي الإعاقة على أداء أعمالهم مسؤولية مجتمعية لا مجرد تبرع عابر؟","options":[{"id":"o2","text":"أنه يهدف إلى عزلهم عن المجتمع"},{"id":"o3","text":"أنه لا يرتبط بأي حاجة حقيقية"},{"id":"o4","text":"أنه يشترط عدم الاستفادة من المشروع"},{"id":"o1","text":"أنه يهيئ فرص المشاركة والاستقلال ويلبّي احتياجات مستمرة"}],"correct_id":"o1","explanation":"ذكر الدرس إقامة مشروعات تمكّن ذوي الإعاقة وتلبي حاجاتهم وبرامج رعايتهم.","page":168},{"id":"u04_l05_q130","lesson_id":"u04_l05","difficulty":"medium","prompt":"لماذا أصبح تقييم أداء الشركات أوسع من حساب الأرباح المالية وحدها؟","options":[{"id":"o4","text":"لأن حماية البيئة لا تتصل بالنشاط الاقتصادي"},{"id":"o1","text":"لأن أثرها الاجتماعي والبيئي والتزامها الأخلاقي أصبح جزءًا من المسؤولية"},{"id":"o3","text":"لأن الشركات غير معنية بالمجتمع"},{"id":"o2","text":"لأن الربح المالي أصبح ممنوعًا دائمًا"}],"correct_id":"o1","explanation":"أوضح الدرس أن المسؤولية الحديثة للشركات تشمل خدمة المجتمع ومكافحة التلوث والتزامات أخلاقية.","page":170},{"id":"u04_l05_q132","lesson_id":"u04_l05","difficulty":"medium","prompt":"لماذا يعد الشعور بالرضا عن أداء خدمة نافعة دافعًا للمسؤولية المجتمعية؟","options":[{"id":"o4","text":"لأنه يقتضي تجاهل حاجات الآخرين"},{"id":"o3","text":"لأنه يجعل العمل النافع غير مهم"},{"id":"o2","text":"لأنه يغني عن كل واجب اجتماعي"},{"id":"o1","text":"لأنه يعزز تقدير الفرد لذاته وإحساسه بدوره الإيجابي"}],"correct_id":"o1","explanation":"ذكر الدرس تقدير الذات والشعور بالدور الإيجابي من دوافع المسؤولية المجتمعية.","page":167},{"id":"u04_l05_q134","lesson_id":"u04_l05","difficulty":"medium","prompt":"نظّمت مجموعة أيامًا طبية مجانية للمحتاجين؛ أي صورة للمسؤولية المجتمعية جسدتها؟","options":[{"id":"o2","text":"نشر الخصومة بين الناس"},{"id":"o1","text":"المساعدة على توفير الرعاية الصحية للفئات المحتاجة"},{"id":"o3","text":"منع التكافل الاجتماعي"},{"id":"o4","text":"الاكتفاء بإعلان تجاري غير نافع"}],"correct_id":"o1","explanation":"ذكر الدرس الأيام الطبية المجانية ضمن صور مساعدة الضعفاء والمحتاجين.","page":168},{"id":"u04_l05_q136","lesson_id":"u04_l05","difficulty":"medium","prompt":"أي عمل تطوعي يرتبط مباشرة بحفظ الموارد البيئية؟","options":[{"id":"o2","text":"إهدار المياه في المرافق العامة"},{"id":"o3","text":"إتلاف الأشجار عمدًا"},{"id":"o4","text":"إهمال تنظيف الأماكن المشتركة"},{"id":"o1","text":"المشاركة في مشروعات المحافظة على المياه"}],"correct_id":"o1","explanation":"ذكر الدرس الحفاظ على المياه وموارد البيئة من أوجه التطوع النافع.","page":168},{"id":"u04_l05_q138","lesson_id":"u04_l05","difficulty":"hard","prompt":"عند انتشار إشاعة تثير الخوف بين السكان، أي سلوك ينسجم مع مسؤولية الفرد تجاه أمن مجتمعه؟","options":[{"id":"o3","text":"تضخيم الأنباء المجهولة"},{"id":"o2","text":"تكرار الإشاعة دون تحقق"},{"id":"o1","text":"التحقق من الأخبار والتصدي للأكاذيب التي تضر بالاستقرار"},{"id":"o4","text":"استغلال الخوف لإثارة الخلافات"}],"correct_id":"o1","explanation":"عدّ الكتاب التصدي للشائعات والأكاذيب من صور حفظ أمن المجتمع واستقراره.","page":168},{"id":"u04_l05_q139","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما الأثر الاجتماعي الناتج من أداء الأفراد واجباتهم وتعاونهم في أعمال الخير؟","options":[{"id":"o1","text":"تقوية الترابط والتراحم والتكافل بين أفراد المجتمع"},{"id":"o4","text":"تعطيل مصالح الفئات المحتاجة"},{"id":"o3","text":"انعدام الثقة المتبادلة"},{"id":"o2","text":"زيادة العزلة والخلافات"}],"correct_id":"o1","explanation":"ذكر الدرس الترابط والتراحم والتكافل ضمن أبرز آثار المسؤولية المجتمعية.","page":169},{"id":"u04_l05_q144","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما الذي يجعل مشروعًا لتدريب ذوي الإعاقة على مهارات العمل مظهرًا للمسؤولية المجتمعية؟","options":[{"id":"o1","text":"تمكينهم من مشروعات تلبي حاجاتهم وتدعم مشاركتهم"},{"id":"o3","text":"إهمال احتياجاتهم التعليمية"},{"id":"o2","text":"الاكتفاء بإبعادهم عن النشاط العام"},{"id":"o4","text":"استبدال مشاركتهم بقرارات لا تراعيهم"}],"correct_id":"o1","explanation":"ذكر الكتاب تمكين ذوي الإعاقة بمشروعات وبرامج تفي بحاجاتهم وتدعمهم.","page":168},{"id":"u04_l05_q147","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما الرابط بين تشبيه المؤمنين بالجسد الواحد وبين الأثر الاجتماعي للمبادرات الخيرية؟","options":[{"id":"o4","text":"أن التطوع يؤدي إلى تباعد الناس"},{"id":"o3","text":"أن كل فرد لا يتأثر بحال الآخرين"},{"id":"o1","text":"التراحم والتكافل وتقوية الترابط بين أفراد المجتمع"},{"id":"o2","text":"إضعاف أواصر المجتمع عند التعاون"}],"correct_id":"o1","explanation":"وضع الكتاب التشبيه في سياق بيان الترابط والتراحم الناجم عن المسؤولية المجتمعية.","page":169},{"id":"u04_l05_q156","lesson_id":"u04_l05","difficulty":"medium","prompt":"إذا دعمت مؤسسة تجارب علمية لموهوبين من المجتمع، فأي صورة من صور المسؤولية تحقق؟","options":[{"id":"o4","text":"حصر العمل في توزيع الأرباح على المساهمين"},{"id":"o1","text":"رعاية المبدعين والابتكار والبحث العلمي"},{"id":"o2","text":"تقييد فرص التعلم لدى الطلبة"},{"id":"o3","text":"منع الأنشطة الصحية والرياضية"}],"correct_id":"o1","explanation":"ذكر الكتاب دعم الموهوبين والبحث العلمي في صور المسؤولية المجتمعية.","page":168},{"id":"u04_l05_q158","lesson_id":"u04_l05","difficulty":"medium","prompt":"لماذا يعد عمل الشركات في مكافحة التلوث ضمن تقييم مسؤوليتها المجتمعية الحديثة؟","options":[{"id":"o4","text":"لأن نشاط الشركات لا يؤثر على البيئة مطلقًا"},{"id":"o2","text":"لأنه يضمن الربح وحده من دون أي أثر آخر"},{"id":"o1","text":"لأنه أثر أخلاقي واجتماعي يتجاوز الأرباح المالية"},{"id":"o3","text":"لأنه يمنع المؤسسات من رعاية المجتمع"}],"correct_id":"o1","explanation":"أوضح الإثراء أن تقييم المؤسسة الحديثة يشمل خدمات للمجتمع ومكافحة التلوث لا الأرباح فقط.","page":170},{"id":"u04_l05_q161","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما واجب المواطنة الذي ذكره تمهيد المسؤولية المجتمعية إلى جانب خدمة الوطن؟","options":[{"id":"o3","text":"حصر البناء الاجتماعي في جهود الدولة وحدها"},{"id":"o4","text":"عدم المشاركة في أي نشاط نافع"},{"id":"o1","text":"احترام القوانين والأنظمة والسعي إلى نشر السلام"},{"id":"o2","text":"إهمال الأنظمة متى تعارضت مع رغبة الفرد"}],"correct_id":"o1","explanation":"أورد الكتاب احترام القانون والمشاركة في التنمية والأمن والسلام ضمن واجبات المواطن.","page":166},{"id":"u04_l05_q165","lesson_id":"u04_l05","difficulty":"hard","prompt":"ما الفارق بين دعم الابتكار بوصفه مسؤولية مجتمعية وبين التبرع المالي العاجل؟","options":[{"id":"o1","text":"دعم الابتكار ينمي القدرات والإنتاج على المدى البعيد بجانب سد الحاجات المباشرة"},{"id":"o4","text":"أن كلا العملين لا يدخلان ضمن المسؤولية"},{"id":"o3","text":"أن التبرع المالي لا يفيد أحدًا مطلقًا"},{"id":"o2","text":"أن دعم الابتكار يمنع كل مساعدة للفقراء"}],"correct_id":"o1","explanation":"عرض الدرس دعم المبدعين والمحتاجين صورًا تكمل بعضها في خدمة المجتمع.","page":168},{"id":"u04_l05_q166","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما دور الفرد عند انتشار إشاعة تضر بالأمن العام وفق شرح المسؤولية المجتمعية؟","options":[{"id":"o1","text":"التصدي للشائعات والأكاذيب وعدم المساهمة في نشرها"},{"id":"o2","text":"تكرار الإشاعة لزيادة انتشارها"},{"id":"o3","text":"التخلي عن كل مصدر موثوق"},{"id":"o4","text":"إهمال أثر الكذب في الأمن"}],"correct_id":"o1","explanation":"ذكر الدرس المحافظة على أمن المجتمع والتصدي للشائعات ضمن المسؤولية.","page":168},{"id":"u04_l05_q168","lesson_id":"u04_l05","difficulty":"medium","prompt":"كيف توسع مفهوم المسؤولية المجتمعية في تقييم الشركات الحديثة؟","options":[{"id":"o2","text":"أصبح يقتصر على حجم الأرباح السنوية"},{"id":"o3","text":"لم يعد يتضمن أي التزام أخلاقي"},{"id":"o1","text":"صار يشمل خدمة المجتمع وحماية البيئة لا الربح المالي وحده"},{"id":"o4","text":"أصبح يعني منع المبادرات الطبية"}],"correct_id":"o1","explanation":"بيّن الإثراء أن أداء الشركات يقيم أيضًا بخدماتها للفقراء والطب والبيئة.","page":170},{"id":"u04_l05_q175","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما الرابط بين إنشاء أيام طبية مجانية ومفهوم المسؤولية المجتمعية؟","options":[{"id":"o1","text":"تقديم الرعاية الصحية والمساعدة للمحتاجين"},{"id":"o2","text":"الاقتصار على تسويق بضائع غير ضرورية"},{"id":"o3","text":"إبعاد المحتاجين عن الخدمات الأساسية"},{"id":"o4","text":"التركيز على المظاهر دون نفع حقيقي"}],"correct_id":"o1","explanation":"صنّف الدرس إقامة الأيام الطبية المجانية ضمن مساعدة الفئات المحتاجة.","page":168},{"id":"u04_l05_q177","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما النتيجة الاجتماعية المتوقعة عندما يُسهم الأفراد في الإصلاح والتكافل؟","options":[{"id":"o3","text":"تراجع التعاون في مواجهة المشكلات"},{"id":"o1","text":"تقوية الترابط والتراحم بين أفراد المجتمع"},{"id":"o4","text":"إلغاء دور العمل التطوعي"},{"id":"o2","text":"زيادة الخلافات دون حل"}],"correct_id":"o1","explanation":"عرض الدرس الترابط والتراحم من آثار قيام الأفراد بمسؤولياتهم المجتمعية.","page":169},{"id":"u04_l05_q178","lesson_id":"u04_l05","difficulty":"medium","prompt":"بأي معيار يتجاوز تقييم المؤسسة الحديثة مجرد مقدار أرباحها؟","options":[{"id":"o3","text":"عدد فروعها دون النظر إلى آثارها"},{"id":"o1","text":"مساهمتها في محاربة الفقر والخدمات الطبية والحد من التلوث"},{"id":"o4","text":"قدرتها على المنافسة دون أي التزام أخلاقي"},{"id":"o2","text":"مقدار إعلاناتها فقط دون أثر اجتماعي"}],"correct_id":"o1","explanation":"ذكر الكتاب أن المسؤولية المجتمعية المعاصرة تشمل دور المؤسسات في معالجة مشكلات المجتمع.","page":170},{"id":"u04_l05_q181","lesson_id":"u04_l05","difficulty":"medium","prompt":"ما الذي يجعل المسؤولية المجتمعية واجبًا أخلاقيًا لا مجرد رغبة في الظهور؟","options":[{"id":"o1","text":"قيام الفرد بما ينفع المجتمع ويحفظ مصالحه العامة"},{"id":"o4","text":"حصر الإصلاح في المؤسسات الرسمية فقط"},{"id":"o2","text":"اشتراط حصول المتطوع على شهرة واسعة"},{"id":"o3","text":"قياس كل عمل بمال يعود إلى صاحبه"}],"correct_id":"o1","explanation":"عرّف الدرس المسؤولية المجتمعية بالتزام الفرد بالنهوض بمجتمعه ورعاية مصالحه.","page":167},{"id":"u04_l06_q113","lesson_id":"u04_l06","difficulty":"medium","prompt":"نشر صورة زميل دون علمه بهدف السخرية منه يعتدي أساسًا على أي حق؟","options":[{"id":"o4","text":"حق تكوين الأحزاب وحده"},{"id":"o2","text":"حق الانتخاب"},{"id":"o1","text":"الكرامة والخصوصية الإنسانية"},{"id":"o3","text":"حق العمل وحده"}],"correct_id":"o1","explanation":"أدرج الكتاب تصوير الأشخاص دون علمهم ونشر الصور المسيئة ضمن انتهاكات الكرامة والخصوصية.","page":174},{"id":"u04_l06_q115","lesson_id":"u04_l06","difficulty":"medium","prompt":"صاحب عمل استوفى عمل أجير ولم يعطه أجره؛ أي حق اعتدى عليه؟","options":[{"id":"o1","text":"حق العمل وما يتصل به من حقوق العامل"},{"id":"o2","text":"حق انتخاب ممثل سياسي"},{"id":"o3","text":"حق الاعتقاد وحده"},{"id":"o4","text":"حق حضور المناسبات العامة"}],"correct_id":"o1","explanation":"استشهد الكتاب بحقوق الأجير وتحذير صاحب العمل من الامتناع عن دفع أجره.","page":176},{"id":"u04_l06_q120","lesson_id":"u04_l06","difficulty":"hard","prompt":"مواطن يطالب بمحاكمة منصفة وبأجره المستحق؛ أي مجالين يعبّران عن مطالبه على الترتيب؟","options":[{"id":"o1","text":"الحقوق الأساسية ثم الحقوق الاقتصادية"},{"id":"o2","text":"الحقوق السياسية ثم الحقوق الاجتماعية"},{"id":"o4","text":"الحقوق الاجتماعية ثم الحقوق السياسية"},{"id":"o3","text":"الحقوق الاقتصادية ثم الحقوق السياسية"}],"correct_id":"o1","explanation":"يورد الكتاب العدل والمحاكمة المنصفة ضمن الحقوق الأساسية والأجر وحقوق العمل ضمن الحقوق الاقتصادية.","page":175}]$wall_questions$::jsonb)
